if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$pid=(int)($_POST['peminjaman_id']??0);$returns=$_POST['detail']??[];try{perpus_require_waktu_pembelajaran($pdo);$pdo->beginTransaction();$st=$pdo->prepare("SELECT d.id,d.buku_id,d.eksemplar_id,d.jumlah,d.status,e.kode_eksemplar,b.judul FROM perpustakaan_detail_peminjaman d JOIN perpustakaan_buku b ON b.id=d.buku_id LEFT JOIN perpustakaan_eksemplar e ON e.id=d.eksemplar_id WHERE d.peminjaman_id=? AND d.status='dipinjam' FOR UPDATE");$st->execute([$pid]);$details=$st->fetchAll();if(!$details)throw new RuntimeException('Tidak ada buku yang masih dipinjam pada transaksi ini.');$updD=$pdo->prepare("UPDATE perpustakaan_detail_peminjaman SET tanggal_kembali=CURDATE(),kondisi_kembali=?,denda=?,status=?,keterangan=? WHERE id=? AND status='dipinjam'");$updE=$pdo->prepare('UPDATE perpustakaan_eksemplar SET status=?,kondisi=? WHERE id=?');$bookIds=[];$auditChanges=[];$returned=0;foreach($details as $d){$data=is_array($returns)?($returns[(string)$d['id']]??[]):[];$do=!empty($data['kembali']);if(!$do)continue;$kondisi=(string)($data['kondisi']??'baik');$denda=max(0,(float)($data['denda']??0));$ket=trim((string)($data['keterangan']??''));if(!in_array($kondisi,['baik','rusak_ringan','rusak_berat','hilang'],true))throw new RuntimeException('Kondisi pengembalian tidak valid.');$detailStatus=$kondisi==='hilang'?'hilang':'kembali';$updD->execute([$kondisi,$denda,$detailStatus,$ket?:null,$d['id']]);$exStatus=$kondisi==='hilang'?'hilang':($kondisi==='baik'?'tersedia':'rusak');if($d['eksemplar_id']){$updE->execute([$exStatus,$kondisi,$d['eksemplar_id']]);$bookIds[$d['buku_id']]=$d['buku_id'];$auditChanges[]=['detail_id'=>(int)$d['id'],'kode'=>$d['kode_eksemplar'],'status_baru'=>$exStatus,'kondisi'=>$kondisi];}else{$legacyPrefix='LEGACY-'.$d['id'].'-';$legacySel=$pdo->prepare("SELECT id FROM perpustakaan_eksemplar WHERE buku_id=? AND kode_eksemplar LIKE ? FOR UPDATE");$legacySel->execute([$d['buku_id'],$legacyPrefix.'%']);$legacyIds=$legacySel->fetchAll(PDO::FETCH_COLUMN);if(!$legacyIds){$insLegacy=$pdo->prepare('INSERT INTO perpustakaan_eksemplar(buku_id,kode_eksemplar,kondisi,status,lokasi,keterangan) SELECT ?,?,?,?,b.lokasi,? FROM perpustakaan_buku b WHERE b.id=?');for($i=1;$i<=max(1,(int)$d['jumlah']);$i++){$code=$legacyPrefix.str_pad((string)$i,4,'0',STR_PAD_LEFT);$insLegacy->execute([$d['buku_id'],$code,$kondisi,$d['status']==='hilang'?'hilang':'dipinjam','Migrasi kompatibilitas transaksi lama #'.$d['id'],$d['buku_id']]);}$legacySel->execute([$d['buku_id'],$legacyPrefix.'%']);$legacyIds=$legacySel->fetchAll(PDO::FETCH_COLUMN);}foreach($legacyIds as $legacyId){$updE->execute([$exStatus,$kondisi,(int)$legacyId]);}$bookIds[$d['buku_id']]=$d['buku_id'];$auditChanges[]=['detail_id'=>(int)$d['id'],'kode'=>'LEGACY','status_baru'=>$exStatus,'kondisi'=>$kondisi];}$returned++;}if($returned===0)throw new RuntimeException('Pilih minimal satu buku yang dikembalikan.');$remain=$pdo->prepare("SELECT COUNT(*) FROM perpustakaan_detail_peminjaman WHERE peminjaman_id=? AND status='dipinjam'");$remain->execute([$pid]);$n=(int)$remain->fetchColumn();$status=$n>0?'sebagian_kembali':'selesai';$pdo->prepare('UPDATE perpustakaan_peminjaman SET status=?,tanggal_selesai=IF(?="selesai",CURDATE(),tanggal_selesai) WHERE id=?')->execute([$status,$status,$pid]);foreach($bookIds as $bookId)perpus_sync_stock($pdo,(int)$bookId);perpus_audit_detail($pdo,'UPDATE',$pid,'Memproses pengembalian buku',[],['status_transaksi'=>$status,'perubahan'=>$auditChanges]);$pdo->commit();perpus_flash('Pengembalian berhasil diproses.');redirect('perpustakaan/pengembalian.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Pengembalian tidak dapat diproses.';}}
$q=trim((string)($_GET['q']??''));$where=["d.status='dipinjam'"];$params=[];if($studentId>0){$where[]='a.siswa_id=?';$params[]=$studentId;}if($q!==''){$where[]='(p.nomor_transaksi LIKE ? OR a.kode_anggota LIKE ? OR s.nama LIKE ? OR g.nama LIKE ?)';$like="%$q%";array_push($params,$like,$like,$like,$like);}$st=$pdo->prepare("SELECT p.id,p.nomor_transaksi,p.tanggal_pinjam,p.tanggal_jatuh_tempo,a.kode_anggota,COALESCE(s.nama,g.nama) nama FROM perpustakaan_peminjaman p JOIN perpustakaan_anggota a ON a.id=p.anggota_id LEFT JOIN siswa s ON s.id=a.siswa_id LEFT JOIN guru g ON g.id=a.guru_id JOIN perpustakaan_detail_peminjaman d ON d.peminjaman_id=p.id WHERE ".implode(' AND ',$where)." GROUP BY p.id ORDER BY p.tanggal_jatuh_tempo ASC,p.id DESC");$st->execute($params);$rows=$st->fetchAll();$selected=null;if($pref){$st=$pdo->prepare("SELECT p.*,a.kode_anggota,COALESCE(s.nama,g.nama) nama,s.id siswa_id FROM perpustakaan_peminjaman p JOIN perpustakaan_anggota a ON a.id=p.anggota_id LEFT JOIN siswa s ON s.id=a.siswa_id LEFT JOIN guru g ON g.id=a.guru_id WHERE p.id=?");$st->execute([$pref]);$selected=$st->fetch();if($selected){$st=$pdo->prepare("SELECT d.*,b.kode_buku,b.judul,e.kode_eksemplar FROM perpustakaan_detail_peminjaman d JOIN perpustakaan_buku b ON b.id=d.buku_id LEFT JOIN perpustakaan_eksemplar e ON e.id=d.eksemplar_id WHERE d.peminjaman_id=? AND d.status='dipinjam'");$st->execute([$pref]);$selected['details']=$st->fetchAll();}}
