const BASE=<?=json_encode(BASE_URL)?>,$=id=>document.getElementById(id);function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function notice(t,e=false){$('retMsg').innerHTML='<div class="alert '+(e?'alert-danger':'alert-success')+'">'+t+'</div>';setTimeout(()=>{$('retMsg').innerHTML=''},5000)}async function openStudent(id){const d=await (await fetch(BASE+'perpustakaan/api.php?type=siswa_loans&student_id='+id,{cache:'no-store'})).json();if(!d.ok||!d.data?.length){notice('Siswa tidak memiliki buku yang sedang dipinjam.','error');return}location.href=BASE+'perpustakaan/pengembalian.php?peminjaman_id='+d.data[0].id+'&siswa_id='+id}
async function resolve(code){code=(code||'').trim();if(!code)return;const d=await (await fetch(BASE+'perpustakaan/api.php?action=resolve_qr&code='+encodeURIComponent(code),{cache:'no-store'})).json();if(!d.ok){SPLASMA_SCANNER_SOUND.beep(false);notice(d.message,'error');return}if(d.type==='siswa'){SPLASMA_SCANNER_SOUND.beep(true);await openStudent(d.data.id);return}notice('QR buku ditemukan. Untuk pengembalian, scan QR siswa terlebih dahulu.','error')}
async function lookup(){const q=$('studentSearch').value.trim(),k=$('kelasManual').value;if(q.length<1){$('studentResults').innerHTML='';return}const d=await (await fetch(BASE+'perpustakaan/api.php?type=siswa&q='+encodeURIComponent(q)+(k?'&kelas_id='+k:''),{cache:'no-store'})).json();$('studentResults').innerHTML=(d.data||[]).map(s=>'<button type="button" data-id="'+s.id+'"><strong>'+esc(s.nama)+'</strong><div class="text-muted small">'+esc(s.nis)+' · '+esc(s.nisn)+' · '+esc(s.kelas)+'</div></button>').join('')||'<div class="p-2 text-muted">Siswa tidak ditemukan.</div>';document.querySelectorAll('#studentResults button').forEach(b=>b.onclick=()=>openStudent(b.dataset.id))}let st;$('studentSearch').addEventListener('input',()=>{clearTimeout(st);st=setTimeout(lookup,180)});$('kelasManual').addEventListener('change',lookup);PerpusScanner.bindUsb('usb',resolve);$('detectCamera').onclick=()=>PerpusScanner.detect();$('startCamera').onclick=()=>PerpusScanner.start(resolve);$('stopCamera').onclick=()=>PerpusScanner.stop();(navigator.serviceWorker?.ready?navigator.serviceWorker.ready:Promise.resolve()).then(()=>PerpusScanner.loadDecoder()).catch(()=>PerpusScanner.loadDecoder());PerpusScanner.detect();
